select lives_ok($$select public.admin_operar_pedido('bb600000-0000-4000-8000-000000000001',0,'cancel')$$,'cancelar');
select is((select stock from public.products where id='bb600000-0000-4000-8000-000000000002'),75,'libera una vez');
select throws_ok($$select public.admin_operar_pedido('bb600000-0000-4000-8000-000000000001',0,'cancel')$$,'SR004',null,'cancelación repetida rechazada');
select is((select name from public.order_items where order_id='bb600000-0000-4000-8000-000000000026'),'Producto histórico','histórico independiente del catálogo');
